window.__BUNDLE = {"body": "<div class=\"wrap legal\">\n  <p><a data-legal-back href=\"../\">← Alle Tests</a></p>\n  <div class=\"eyebrow\">Tests von Iryna Voznesenskaya</div>\n  <h1>Impressum</h1>\n  <p><b>Iryna Wiederkehr (Iryna Voznesenskaya)</b><br>Coaching für das Ankommen nach einem Umzug</p>\n  <div data-legal-has><p><span data-legal=\"address\"></span></p><p data-legal-mail>E-Mail: <span data-legal=\"email\"></span></p></div>\n  <p class=\"placeholder\" data-legal-missing>Eine E-Mail-Adresse wird hier in Kürze ergänzt. Bis dahin erreichst du mich über <a href=\"https://www.instagram.com/iryna.voznesenskaya/\" target=\"_blank\" rel=\"noopener\">Instagram @iryna.voznesenskaya</a> oder <a href=\"https://t.me/IrynaNeuroCoach_channel\" target=\"_blank\" rel=\"noopener\">Telegram</a>.</p>\n  <p>In der Schweiz arbeite ich ausschliesslich als Coach. Coaching ist keine Psychotherapie und ersetzt keine psychologische oder medizinische Hilfe. Als Psychologin arbeite ich nur mit Klientinnen und Klienten in der Ukraine, auf Grundlage meiner ukrainischen Qualifikation.</p>\n  <h2>Urheberrecht</h2>\n  <p>Texte, Tests, Illustrationen und Gestaltung der Website: © <span data-legal-year></span> Iryna Voznesenskaya. Kopieren und Verwenden ohne schriftliche Erlaubnis ist nicht gestattet.</p>\n  <h2>Links</h2>\n  <p>Die Website enthält Links zu Instagram, Telegram und anderen externen Angeboten. Für deren Inhalte sind die jeweiligen Betreiber verantwortlich.</p>\n  <p><a href=\"../privacy/\">Datenschutzerklärung</a></p>\n</div>\n", "scripts": ["/* Настройки сайта, общие для всех тестов */\n// Ссылка веб-приложения Google Apps Script (заканчивается на /exec). Одна на все тесты.\nconst ENDPOINT = 'https://script.google.com/macros/s/AKfycbyizp1XjzNdrUj4WHgj4Vyj81QhjY2D7puqyeY3LaweWB4mePxPhfHCx5fIsfaJy9hV/exec';\n// Адрес сайта после размещения, например 'https://irina-tests.netlify.app/' (нужен для ссылок в PDF)\nconst SITE_URL = 'https://irynawiederkehr-cmd.github.io/tests/';\n// Ссылки на тесты, пока сайт не размещён (используются для кнопки «Поделиться» и блока «Пройди также»).\n// После размещения сайта достаточно заполнить SITE_URL — эти ссылки больше не понадобятся.\nconst TEST_LINKS = {\n  'roza-lyubvi': 'https://claude.ai/artifact/6Nv7pCtqpAd9xoWUkvEwS1',\n  'kompas': 'https://claude.ai/artifact/5TPCgkiVSZEr8H2g8d1UkY'\n};\n// Деловой почтовый адрес и e-mail для «Выходных данных» и «Политики конфиденциальности».\n// ЛИЧНЫЙ АДРЕС ИРИНЫ НЕ УКАЗЫВАТЬ. Пока поля пустые, на страницах стоит временная строка «скоро появятся».\n// address — строки через \\n, например 'Musterstrasse 1\\n8000 Zürich'.\nconst LEGAL = {\n  address: {\n    ru: 'проспект Бажана, 5-Г\\n02121 Киев, Украина',\n    uk: 'просп. Миколи Бажана, 5-Г\\n02121 Київ, Україна',\n    de: 'Mykoly-Bazhana-Prospekt 5-H\\n02121 Kyjiw, Ukraine',\n    en: '5-H Mykoly Bazhana Avenue\\n02121 Kyiv, Ukraine'\n  },\n  email: 'voznesenskaya.iryna@gmail.com', since: '02.10.2026'\n};\n", "const BRAND = 'coach';", "/* =====================================================================\n   Библиотека значков — общая для всех тестов (с 02.10.2026).\n   Один стиль: сетка 24×24, мягкая заливка светлым тоном + тонкий контур глубоким тоном того же цвета\n   (как акварель с контуром в утверждённой палитре), линия 1.8, скруглённые концы.\n   Использование: ico('flame', '#C25468', '#EEA9B3', 26) — имя, цвет контура, цвет заливки, размер.\n   Если заливка не задана, берётся очень светлый тон контура.\n   Каталог с картинками всех значков — файл «Библиотека значков.html».\n   ===================================================================== */\nconst ICONS = {\n  /* ступени, дом, опоры */\n  earth:    (c, f, s) => `<circle cx=\"12\" cy=\"8\" r=\"3.2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M3 15c3-2 6-2 9 0s6 2 9 0M3 19.5c3-2 6-2 9 0s6 2 9 0\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  hearth:   (c, f, s) => `<path d=\"M12 3c3 4 6.5 6 6.5 10.5a6.5 6.5 0 0 1-13 0c0-3 2-4.5 3-6.5 1 2 2 3 3 3 0-3-1-5 .5-7z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M9 21h6\" stroke=\"${c}\" ${s}/>`,\n  door:     (c, f, s) => `<rect x=\"6\" y=\"3\" width=\"12\" height=\"18\" rx=\"1.5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"14.8\" cy=\"12.5\" r=\"1.2\" fill=\"${c}\"/><path d=\"M3 21h18\" stroke=\"${c}\" ${s}/>`,\n  key:      (c, f, s) => `<circle cx=\"8\" cy=\"12\" r=\"4.2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12.2 12H21M18 12v3M21 12v3\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  workshop: (c, f, s) => `<path d=\"M13.5 4.5l6 6-3 3-6-6z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 9l-8 8 3 3 8-8\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  sprout:   (c, f, s) => `<path d=\"M12 21v-9\" stroke=\"${c}\" ${s}/><path d=\"M12 13c-4.5 0-7-3-7-7 4.5 0 7 3 7 7zM12 11c0-4.5 3-7 7.5-7 0 4.5-3 7-7.5 7z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  hill:     (c, f, s) => `<path d=\"M2 19.5l7-9.5 4 5 3-3.5 6 8z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"17\" cy=\"5.5\" r=\"2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  sky:      (c, f, s) => `<path d=\"M12 3l1.9 5.6L19.5 10.5l-5.6 1.9L12 18l-1.9-5.6L4.5 10.5l5.6-1.9z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"19\" cy=\"19\" r=\"1.4\" fill=\"${c}\"/><circle cx=\"5\" cy=\"19.5\" r=\"1\" fill=\"${c}\"/>`,\n  home:     (c, f, s) => `<path d=\"M3.5 11 12 4l8.5 7v9.5h-17z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M10 20.5v-5h4v5\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  homeLight:(c, f, s) => `<path d=\"M3.5 11 12 4l8.5 7v9.5h-17z\" fill=\"none\" stroke=\"${c}\" ${s}/><rect x=\"9\" y=\"11.5\" width=\"6\" height=\"5\" rx=\"1\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 11.5v5M9 14h6\" stroke=\"${c}\" stroke-width=\"1.2\"/>`,\n  /* отношения */\n  flame:    (c, f, s) => `<path d=\"M12 3c3 4 6.5 6 6.5 10.5a6.5 6.5 0 0 1-13 0c0-3 2-4.5 3-6.5 1 2 2 3 3 3 0-3-1-5 .5-7z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 20a2.6 2.6 0 0 1-2.6-2.6c0-1.6 1.4-2.4 2.6-4 1.2 1.6 2.6 2.4 2.6 4A2.6 2.6 0 0 1 12 20z\" fill=\"${c}\" fill-opacity=\".35\"/>`,\n  rings:    (c, f, s) => `<circle cx=\"9\" cy=\"12\" r=\"5.2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"15\" cy=\"12\" r=\"5.2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  heart:    (c, f, s) => `<path d=\"M12 20s-7.5-4.6-7.5-10.2A4.3 4.3 0 0 1 12 7.3a4.3 4.3 0 0 1 7.5 2.5C19.5 15.4 12 20 12 20z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  bridge:   (c, f, s) => `<path d=\"M2.5 15.5C5 9.5 19 9.5 21.5 15.5z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M2.5 15.5h19M7 12v3.5M12 10.7v4.8M17 12v3.5\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M2.5 19.5c2-1.2 4-1.2 6 0s4 1.2 6 0 4-1.2 6 0\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  trees:    (c, f, s) => `<path d=\"M7.5 21v-5M16.5 21v-5\" stroke=\"${c}\" ${s}/><path d=\"M7.5 16.5c-2.6 0-4.3-2-4.3-4.6S5 6 7.5 4c2.5 2 4.3 5.3 4.3 7.9s-1.7 4.6-4.3 4.6z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M16.5 16.5c-2.6 0-4.3-2-4.3-4.6S14 6 16.5 4c2.5 2 4.3 5.3 4.3 7.9s-1.7 4.6-4.3 4.6z\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M3 21h18\" stroke=\"${c}\" ${s}/>`,\n  hands:    (c, f, s) => `<path d=\"M3 13.5l4.5-4 4 2.5 4-2.5 5.5 4-6 5.5h-6z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M11.5 12l2.5 2.5M9.5 14l2 2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  speech:   (c, f, s) => `<path d=\"M4 5.5h16v10H10l-5 4v-4H4z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M8 9.5h8M8 12.5h5\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  people:   (c, f, s) => `<circle cx=\"8.5\" cy=\"8.5\" r=\"3\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"16\" cy=\"9.5\" r=\"2.6\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M3 19.5c.6-3.4 2.9-5.3 5.5-5.3s4.9 1.9 5.5 5.3M13.5 15c.8-.5 1.6-.7 2.5-.7 2.3 0 4.3 1.7 4.9 4.6\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  shield:   (c, f, s) => `<path d=\"M12 3l7.5 3v5.5c0 4.6-3.2 8-7.5 9.5-4.3-1.5-7.5-4.9-7.5-9.5V6z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M9 12l2.2 2.2L15.5 10\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  anchor:   (c, f, s) => `<circle cx=\"12\" cy=\"5.5\" r=\"2.3\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 7.8V20M8 11h8M4.5 14c.5 3.5 3.6 6 7.5 6s7-2.5 7.5-6\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  /* путь, рефлексия, эксперимент */\n  compass:  (c, f, s) => `<circle cx=\"12\" cy=\"12\" r=\"8.5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M14.8 9.2l-1.8 4.8-4.8 1.8 1.8-4.8z\" fill=\"${c}\" fill-opacity=\".85\" stroke=\"${c}\" stroke-width=\"1.2\" stroke-linejoin=\"round\"/>`,\n  path:     (c, f, s) => `<path d=\"M3 20.5H8V16.5H12V12.5H16V8.5H21V20.5Z\" fill=\"${f}\" stroke=\"none\"/><path d=\"M3 20.5H8V16.5H12V12.5H16V8.5H21\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M18.5 8.5V3\" stroke=\"${c}\" ${s}/><path d=\"M18.5 3.2H22L21 4.6L22 6H18.5\" fill=\"#fff\" stroke=\"${c}\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><circle cx=\"5.5\" cy=\"17.3\" r=\"1.3\" fill=\"${c}\"/>`,\n  signpost: (c, f, s) => `<path d=\"M12 3v18M8.5 21h7\" stroke=\"${c}\" ${s}/><path d=\"M12 5h6.3l2.2 2.2-2.2 2.2H12z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 11.5H5.7l-2.2 2.2 2.2 2.2H12z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  eye:      (c, f, s) => `<path d=\"M2.5 12S6 5.5 12 5.5 21.5 12 21.5 12 18 18.5 12 18.5 2.5 12 2.5 12z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><circle cx=\"12\" cy=\"12\" r=\"3\" fill=\"none\" stroke=\"${c}\" ${s}/><circle cx=\"12\" cy=\"12\" r=\"1\" fill=\"${c}\"/>`,\n  explore:  (c, f, s) => `<circle cx=\"10.5\" cy=\"10.5\" r=\"6\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M15 15l5.5 5.5\" stroke=\"${c}\" ${s}/><path d=\"M8 9.5a2.8 2.8 0 0 1 2.5-2\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  flask:    (c, f, s) => `<path d=\"M9.5 3.5v5.5L4.5 18a2 2 0 0 0 1.8 3h11.4a2 2 0 0 0 1.8-3l-5-9V3.5\" fill=\"none\" stroke=\"${c}\" ${s}/><path d=\"M6.8 15h10.4l1.6 3a1.2 1.2 0 0 1-1.1 1.8H6.3A1.2 1.2 0 0 1 5.2 18z\" fill=\"${f}\" stroke=\"${c}\" stroke-width=\"1.2\"/><path d=\"M8 3.5h8\" stroke=\"${c}\" ${s}/>`,\n  mirror:   (c, f, s) => `<ellipse cx=\"12\" cy=\"9.5\" rx=\"5.5\" ry=\"6.5\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 16v5M8.5 21h7M9.5 7a3 3 0 0 1 2-1.6\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  pen:      (c, f, s) => `<path d=\"M15.5 4.5l4 4L9 19l-5 1 1-5z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M13.5 6.5l4 4\" stroke=\"${c}\" ${s}/>`,\n  book:     (c, f, s) => `<path d=\"M3.5 5.5c3-1 5.8-.8 8.5 1 2.7-1.8 5.5-2 8.5-1v13c-3-1-5.8-.8-8.5 1-2.7-1.8-5.5-2-8.5-1z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 6.5v13\" stroke=\"${c}\" ${s}/>`,\n  seed:     (c, f, s) => `<path d=\"M12 20c-3.6 0-6-2.6-6-6.3C6 9.5 9 6 12 4c3 2 6 5.5 6 9.7 0 3.7-2.4 6.3-6 6.3z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 20v-7.5\" stroke=\"${c}\" ${s}/>`,\n  sun:      (c, f, s) => `<circle cx=\"12\" cy=\"12\" r=\"4.2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M12 2.8v2.4M12 18.8v2.4M2.8 12h2.4M18.8 12h2.4M5.5 5.5l1.7 1.7M16.8 16.8l1.7 1.7M5.5 18.5l1.7-1.7M16.8 7.2l1.7-1.7\" stroke=\"${c}\" ${s}/>`,\n  moon:     (c, f, s) => `<path d=\"M19 15.5A8 8 0 0 1 8.5 5a8 8 0 1 0 10.5 10.5z\" fill=\"${f}\" stroke=\"${c}\" ${s}/>`,\n  lantern:  (c, f, s) => `<path d=\"M9 6h6l1.5 3v8L15 20H9l-1.5-3V9z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M10 3.5h4M12 3.5V6M12 11v4\" stroke=\"${c}\" ${s}/>`,\n  cup:      (c, f, s) => `<path d=\"M4.5 9h12v5a5 5 0 0 1-5 5h-2a5 5 0 0 1-5-5z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M16.5 10.5h1.5a2.3 2.3 0 0 1 0 4.6h-1.8M8 3.5c-.8 1 .8 2-.1 3M12 3.5c-.8 1 .8 2-.1 3\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  mask:     (c, f, s) => `<path d=\"M4 6.5c5-2 11-2 16 0v5.5c0 4.5-3.6 8-8 8s-8-3.5-8-8z\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M7.5 11c1-.8 2.5-.8 3.5 0M13 11c1-.8 2.5-.8 3.5 0M9 15.5c1.8 1.2 4.2 1.2 6 0\" fill=\"none\" stroke=\"${c}\" ${s}/>`,\n  lock:     (c, f, s) => `<rect x=\"5\" y=\"10.5\" width=\"14\" height=\"10\" rx=\"2\" fill=\"${f}\" stroke=\"${c}\" ${s}/><path d=\"M8 10.5V8a4 4 0 0 1 8 0v2.5M12 14.5v2.5\" fill=\"none\" stroke=\"${c}\" ${s}/>`\n};\n/* светлый тон цвета для заливки по умолчанию */\nconst icoSoft = c => { const h = String(c).replace('#', ''); if (h.length !== 6) return 'none';\n  return '#' + [0, 2, 4].map(i => Math.round(parseInt(h.substr(i, 2), 16) * .3 + 255 * .7).toString(16).padStart(2, '0')).join(''); };\nfunction ico(name, line = '#2E5A88', fill, size = 24){\n  const draw = ICONS[name] || ICONS.seed;\n  const s = 'stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"';\n  return `<svg viewBox=\"0 0 24 24\" width=\"${size}\" height=\"${size}\" aria-hidden=\"true\">${draw(line, fill || icoSoft(line), s)}</svg>`;\n}\n\n/* знак-аватар Ирины: цветок-мандала (с 03.10.2026) */\nconst AVATAR_SVG = '<svg viewBox=\"0 0 100 100\" aria-hidden=\"true\"><circle cx=\"50\" cy=\"50\" r=\"46\" fill=\"#FFFCF8\" stroke=\"#6E4F3C\" stroke-width=\"3\"/><g transform=\"rotate(22.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(67.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(112.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(157.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(202.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(247.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(292.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(337.5 50 50)\"><path d=\"M50 50 C42 40 43 24 50 15 C57 24 58 40 50 50Z\" fill=\"#E3E6D6\" stroke=\"#66704F\" stroke-width=\"2\"/></g><g transform=\"rotate(0.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(45.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(90.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(135.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(180.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(225.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(270.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><g transform=\"rotate(315.0 50 50)\"><path d=\"M50 50 C45 43 45 32 50 26 C55 32 55 43 50 50Z\" fill=\"#EADFCF\" stroke=\"#6E4F3C\" stroke-width=\"2\"/></g><circle cx=\"50\" cy=\"50\" r=\"7\" fill=\"#B98324\"/></svg>';\n", "/* язык страницы: задаёт загрузчик (ru, uk, de, en) */\nconst DATE_LOCALE = ({ ru:'ru-RU', uk:'uk-UA', de:'de-CH', en:'en-GB' })[(typeof LANG !== 'undefined') ? LANG : 'ru'] || 'ru-RU';\n/* =====================================================================\n   Общие тексты и блоки для всех тестов Ирины Вознесенской.\n   Меняешь здесь — меняется во всех тестах сразу.\n   ===================================================================== */\n\n/* ---------- Обо мне и контакты ---------- */\nconst AUTHOR = {\n  name: 'Iryna Voznesenskaya',\n  about: 'ICF-Coach in der Schweiz und Psychologin in der Ukraine.',\n  coach: { place: 'Schweiz · Zürich', title: 'Coach', badge: \"Transformations-Coach und Neurocoach ICF\", text: [\"Ich begleite Menschen, die ihr Land aus den unterschiedlichsten Gründen verlassen haben und sich an einem neuen Ort ein Leben aufbauen. Ich weiss, wie viel Kraft das kostet: Stress, der auch nach den Papieren nicht nachlässt, fremde Regeln, eine Sprache, in der das Wichtigste noch nicht über die Lippen will, und das leise Gefühl, mit dem Zuhause auch einen Teil von sich zurückgelassen zu haben.\", \"In unserer Arbeit gehen wir in die Tiefe, über die emotionale Intelligenz, dorthin, wo deine Reaktionen und Entscheidungen entstehen. Deshalb geschieht Veränderung von innen und bleibt bei dir. Schritt für Schritt fühlst du dich im fremden Land zugehörig, findest deinen Platz, setzt dich behutsam neu zusammen und wirst hier gleichsam neu geboren, um dein glückliches Leben zu leben.\"], legal: \"In der Schweiz arbeite ich ausschliesslich als Coach. Coaching ist keine Psychotherapie und ersetzt keine psychologische oder medizinische Hilfe.\",\n           instagram: 'https://www.instagram.com/iryna.voznesenskaya/', telegram: 'https://t.me/IrynaNeuroCoach_channel' },\n  psy:   { place: 'Ukraine · Kyjiw', title: 'Psychologin in der Ukraine', badge: \"Psychologin · Analytische Psychologie nach C. G. Jung\", text: [\"Ich arbeite mit Menschen, denen lebendige, warme Beziehungen wichtig sind. Oft geht die Liebe nicht verloren, sie wird nur leise unter Müdigkeit, Kränkungen und Alltag, und jeder bleibt mit seinem Schmerz allein.\", \"Ich arbeite in der Tiefe unbewusster Prozesse: im tiefen Dialog, mit Metaphern, Bildern und Symbolen, gestützt auf die Analytische Psychologie von Carl Gustav Jung. So wird sichtbar, was sich schwer in Worte fassen lässt, und ein Paar bekommt die Chance, einander wieder zu hören und Nähe und Wärme zurückzugewinnen.\"], legal: \"Als Psychologin arbeite ich nur mit Klientinnen und Klienten in der Ukraine, auf Grundlage meiner ukrainischen Qualifikation.\",\n           instagram: 'https://www.instagram.com/voznesenskayairyna.psy/', telegram: 'https://t.me/IrynaVoznesenska_psy' }\n};\n\n/* ---------- Все тесты (для главной и блока «Пройди также») ---------- */\nconst TESTS = [\n  { id: 'roza-lyubvi', path: 'roza-lyubvi/', name: 'Die Rose der Liebe', slogan: 'Damit ihr einander wieder hört und Wärme in eure Beziehung zurückkehrt', brand: 'psy', tag: 'Für Paare · 15 Minuten',\n    text: 'Drei Rollen in der Beziehung: Anziehung, Nähe und Verantwortung. Finde heraus, welche Rollen deutlich klingen, welche leiser geworden sind und wie ihr einander begegnet.' },\n  { id: 'kompas', path: 'kompas/', name: 'Kompass der Anpassung', slogan: 'Wo du gerade im neuen Land stehst und wohin es weitergeht', brand: 'coach', tag: 'Für dich · 10 Minuten',\n    text: 'Wo du gerade nach dem Umzug stehst: sechs Bereiche deines neuen Lebens, dein Weg zwischen zwei Kulturen und der nächste kleine Schritt.' }\n];\n\nconst handle = url => '@' + url.replace(/\\/+$/, '').split('/').pop();\nconst pickOne = arr => arr[Math.floor(Math.random() * arr.length)];\nconst BASE = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n\nfunction practiceHtml(key){\n  const p = AUTHOR[key];\n  const links = [\n    p.instagram ? `<a href=\"${p.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram ${handle(p.instagram)}</a>` : '',\n    p.telegram ? `<a href=\"${p.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram-Kanal</a>` : ''\n  ].filter(Boolean).join('');\n  return `<div class=\"practice ${key}\"><span class=\"place\">${p.place}</span><h4>${p.title}</h4>${p.badge ? `<span class=\"pbadge\">${p.badge}</span>` : ''}${[].concat(p.text).map(t => `<p>${t}</p>`).join('')}${p.legal ? `<p class=\"plegal\">${p.legal}</p>` : ''}<div class=\"links\">${links}</div></div>`;\n}\nfunction authorHtml(label = 'Über die Autorin des Tests'){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  return `<div class=\"blk author\"><div class=\"eyebrow\">${label}</div>\n    <div class=\"who\"><div class=\"mono av\">${AVATAR_SVG}</div><div><b>${AUTHOR.name}</b><span>${AUTHOR.about}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div></div>`;\n}\nfunction footerLine(){\n  return BRAND === 'coach' ? 'Iryna Voznesenskaya · ICF-Coach (Schweiz) · Psychologin (Ukraine)' : 'Iryna Voznesenskaya · Psychologin (Ukraine) · ICF-Coach (Schweiz)';\n}\n\n/* ---------- Приветствие и обязательный мини-опрос ---------- */\nconst SURVEY = {\n  heard: { q: 'Woher kennst du mich?', opts: ['Instagram','Telegram','Empfehlung von Freunden oder Bekannten','Google-Suche','Facebook','Anderes'] },\n  interest: { q: 'Was interessiert dich?', opts: ['Psychologie: Beziehung als Paar','Coaching: Anpassung nach dem Umzug und zu sich selbst finden','Einfach so, aus Neugier'] }\n};\nconst GREET = {\n  head: ['Hallo! Ich bin {A}','Schön, dass du da bist! Ich heisse {A}','Willkommen! Ich bin {A}','Grüss dich! Ich bin {A}'],\n  about: ['ICF-Coach in der Schweiz und Psychologin in der Ukraine.','Ich arbeite in zwei Ländern: als ICF-Coach in der Schweiz und als Psychologin in der Ukraine.','Ich helfe Menschen, zu sich selbst zu finden und warme Beziehungen aufzubauen: als ICF-Coach in der Schweiz und als Psychologin in der Ukraine.'],\n  ask: ['Beantworte bitte vor dem Test drei kurze Fragen. So verstehe ich besser, wie ich dir nützlich sein kann.',\n        'Drei kurze Fragen vor dem Start, und dann geht es direkt zum Test.',\n        'Mir ist wichtig zu wissen, wer meine Tests macht. Beantworte bitte drei kurze Fragen.']\n};\nfunction greetingHtml(){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  const group = key => `<fieldset class=\"survey\"><legend>${SURVEY[key].q} *</legend>${SURVEY[key].opts.map((o, i) =>\n    `<label class=\"check\"><input type=\"checkbox\" id=\"sv-${key}-${i}\" data-sv=\"${key}\" value=\"${o}\"> <span>${o}</span></label>`).join('')}</fieldset>`;\n  return `<div class=\"blk author greet\">\n    <div class=\"who\"><div class=\"mono av\">${AVATAR_SVG}</div><div><b>${pickOne(GREET.head).replace('{A}', AUTHOR.name)}</b><span>${pickOne(GREET.about)}</span></div></div>\n    <p class=\"greet-more\"><a href=\"${BASE}#about\">Mehr über mich und meine Arbeit →</a></p>\n    <div class=\"stack\" style=\"gap:10px\"><p class=\"note\">${pickOne(GREET.ask)} Du kannst mehrere Antworten ankreuzen.</p>\n      <div class=\"surveys\">${group('heard')}${group('interest')}</div>\n      <p class=\"err\" id=\"svErr\" hidden></p>\n      <div><button class=\"btn\" type=\"button\" id=\"svGo\">Weiter zum Test</button></div></div></div>`;\n}\nfunction surveyAnswers(){\n  const pick = key => [...document.querySelectorAll(`input[data-sv=\"${key}\"]:checked`)].map(i => i.value);\n  return { heard: pick('heard'), interest: pick('interest') };\n}\n\n/* ---------- Живое приглашение в работу (тексты каждый раз собираются заново) ---------- */\nconst INVITES = {\n  psy: {\n    open: ['{N}, danke für deine ehrlichen Antworten.',\n           '{N}, du machst schon einen wichtigen Schritt: Du schaust ehrlich auf eure Beziehung.',\n           '{N}, diese Auswertung ist erst der Anfang eines Gesprächs.',\n           '{N}, der Test zeigt ein Bild, echte Veränderung beginnt im Gespräch.',\n           '{N}, hinter jeder Zahl in dieser Auswertung steht deine Geschichte.'],\n    body: ['Die Zahlen zeigen, wo es in eurer Beziehung still geworden ist. Doch dahinter steht immer etwas Eigenes: Müdigkeit, Kränkungen, Gewohnheiten, unausgesprochene Erwartungen. Im Gespräch schauen wir behutsam auf deine Situation und finden erste Schritte, damit {F}.',\n           'Manchmal genügt eine einzige treffende Frage, damit ein Paar einander wieder hört. Wenn du dir wünschst, dass {F}, lade ich dich zu einem Gespräch ein: ruhig, behutsam, ohne Bewertung.',\n           'Beziehungen verändern sich nicht durch Wissen, sondern durch neue Handlungen. Ich helfe Paaren, diese Handlungen zu finden und sie nicht nach einer Woche wieder aufzugeben. Lass uns gemeinsam schauen, was es braucht, damit {F}.',\n           'Den Weg zur Veränderung kann man allein gehen oder mit Unterstützung. Im Gespräch schauen wir dein Dreieck an und überlegen, was es braucht, damit {F}.',\n           'Viele Paare leben jahrelang mit derselben Spannung, weil sie nicht wissen, wie sie das Gespräch beginnen sollen. Ich helfe dir, es so zu beginnen, dass {F}.'],\n    cta:  ['Melde dich für ein Kennenlerngespräch von 30 Minuten an: Wir besprechen dein Ergebnis und entscheiden, ob eine weitere Arbeit an der Beziehung sinnvoll ist.',\n           '30 Minuten online. Du erzählst, ich höre zu und stelle Fragen. Nach dem Gespräch wird klarer, was in eurer Beziehung passiert und wo du anfangen kannst.',\n           'Das erste Gespräch dauert 30 Minuten. Das reicht, um dein Anliegen zu verstehen und einen Weg für die Arbeit an der Beziehung zu skizzieren.'],\n    title: ['Ich lade dich zu einem Gespräch von 30 Minuten ein','Lass uns über eure Beziehung sprechen','Der nächste Schritt: ein Gespräch'],\n    legal: 'Psychologische Beratungen finden online für Klientinnen und Klienten in der Ukraine statt.'\n  },\n  coach: {\n    open: ['{N}, danke, dass du dir Zeit für dich nimmst.',\n           '{N}, du machst schon einen wichtigen Schritt: Du schaust ehrlich und behutsam auf dich.',\n           '{N}, diese Auswertung ist erst der Anfang des Weges.',\n           '{N}, manchmal öffnet ein Test mehr Fragen als Antworten. Und das ist gut so.',\n           '{N}, alles, was du jetzt siehst, kann zu einer Stütze werden.'],\n    body: ['Ein Umzug in ein neues Land verändert alles: Sprache, Gewohnheiten, Rollen in der Familie und sogar, wie wir uns selbst sehen. Im Coaching suchen wir deine Stützen in der neuen Welt und helfen dir Schritt für Schritt, {F}.',\n           'Wenn sich das Land ändert, verändern auch wir uns. Manchmal fühlt sich das an, als würde man sich selbst verlieren. Ich helfe dir, dich neu zu finden, um {F}.',\n           'Du hast schon einen grossen Weg hinter dir. Coaching hilft dir, diese Erfahrung in Kraft zu verwandeln und {F}.',\n           'Die Antworten sind schon in dir, aber im Trubel des neuen Lebens sind sie schwer zu hören. In der Arbeit mit mir findest du deine Antworten und entscheidest, was dir hilft, {F}.',\n           'Anpassung bedeutet nicht nur Papiere und Sprache. Es ist die Suche nach dem eigenen Platz. Lass uns gemeinsam schauen, was dir hilft, {F}.'],\n    cta:  ['Melde dich für ein Kennenlerngespräch von 30 Minuten an: Wir sprechen über dein Anliegen und darüber, wie die Arbeit an dir selbst aussehen kann.',\n           '30 Minuten online. Du erzählst, was dir gerade wichtig ist, ich stelle Fragen. Nach dem Gespräch wird klarer, wohin du gehen willst.',\n           'Das erste Gespräch dauert 30 Minuten. Das reicht, um dein Anliegen zu verstehen und erste Schritte zu skizzieren.'],\n    title: ['Ich lade dich zu einem Gespräch von 30 Minuten ein','Lass uns über dich sprechen','Der nächste Schritt: ein Gespräch'],\n    legal: 'Coaching ist keine Psychotherapie und ersetzt keine psychologische oder medizinische Behandlung.'\n  }\n};\nconst INVITE_FOCUS_DEFAULT = { psy: 'in eurer Beziehung mehr Wärme und Verständnis entsteht', coach: 'deinen Platz in der neuen Welt zu finden' };\nlet inviteSeed = null;\nfunction resetInvite(){ inviteSeed = null; }\nfunction invitePractice(country){\n  // как психолог Ирина работает только с клиентами в Украине; остальных приглашаем в коучинг\n  if (BRAND === 'psy' && country && country !== 'Украина') return 'coach';\n  return BRAND;\n}\nfunction inviteHtml(ctx){\n  if (!inviteSeed) inviteSeed = Array.from({length:6}, () => Math.random());\n  const key = invitePractice(ctx.country);\n  const P = INVITES[key], A = AUTHOR[key];\n  const pick = (arr, i) => arr[Math.floor(inviteSeed[i] * arr.length)];\n  const N = ctx.name || '';\n  const F = (ctx.focus && ctx.focus[key]) || INVITE_FOCUS_DEFAULT[key];\n  const fill = t => { let s = N ? t.replace('{N}', N) : t.replace('{N}, ', ''); s = s.replace('{F}', F); return s.charAt(0).toUpperCase() + s.slice(1); };\n  const links = [A.telegram ? `<a href=\"${A.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram: ${A.telegram.replace('https://','')}</a>` : '',\n                 A.instagram ? `<a href=\"${A.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram: ${handle(A.instagram)}</a>` : ''].filter(Boolean);\n  const other = key === 'psy' ? 'coach' : 'psy';\n  const wantsOther = (ctx.interest || []).some(x => other === 'coach' ? /^Coaching/.test(x) : /^Psychologie/.test(x));\n  const otherLine = wantsOther && !(other === 'psy' && ctx.country && ctx.country !== 'Украина')\n    ? `<p class=\"note\">Dich interessiert auch die Richtung «${AUTHOR[other].title}». Mehr über diese Arbeit erfährst du hier: <a href=\"${AUTHOR[other].telegram}\" target=\"_blank\" rel=\"noopener\">${AUTHOR[other].telegram.replace('https://','')}</a></p>` : '';\n  return `<div class=\"blk invite ${key}\">\n    <div class=\"eyebrow\">${key === 'psy' ? 'Arbeit an der Beziehung' : 'Arbeit an dir selbst'}</div>\n    <h2>${pick(P.title, 0)}</h2>\n    <p class=\"lead\"><b>${fill(pick(P.open, 1))}</b></p>\n    <p>${fill(pick(P.body, 2))}</p>\n    <div class=\"invite-cta\"><p>${fill(pick(P.cta, 3))}</p>\n      <p><b>So meldest du dich an:</b> Schreib mir das Wort <b>«TERMIN»</b>, und ich schlage dir eine passende Zeit vor.</p>\n      <div class=\"invite-links\">${links.join('')}</div></div>\n    ${otherLine}\n    <p class=\"note\">${P.legal}</p></div>`;\n}\n\n/* ---------- Пройди также ---------- */\nfunction testUrl(t){\n  if (typeof SITE_URL !== 'undefined' && SITE_URL) return SITE_URL.replace(/\\/?$/, '/') + t.path;\n  if (typeof TEST_LINKS !== 'undefined' && TEST_LINKS[t.id]) return TEST_LINKS[t.id];\n  return BASE + t.path;\n}\nfunction moreTestsHtml(currentId){\n  const list = TESTS.filter(t => t.id !== currentId);\n  if (!list.length) return '';\n  return `<div class=\"blk more\"><div class=\"eyebrow\">Mach auch diesen Test</div>\n    <div class=\"tcards\">${list.map(t => `<a class=\"tcard ${t.brand}\" href=\"${testUrl(t)}\" target=\"_blank\" rel=\"noopener\">\n      <span class=\"ttag\">${t.tag}</span><b>${t.name}</b><span class=\"tslogan\">${t.slogan}</span><span>${t.text}</span><span class=\"tgo\">Zum Test →</span></a>`).join('')}</div></div>`;\n}\n\n/* ---------- Об этом опроснике + дисклеймер ---------- */\nconst DISCLAIMER = [\n  'Dieser Fragebogen ist ein Werkzeug zur Reflexion, Selbstbeobachtung und persönlichen Entwicklung und ein Anlass für Gespräche. Er ist keine psychologische oder medizinische Diagnostik und kein psychotherapeutischer Befund und ersetzt keine Beratung durch eine Fachperson.',\n  'Die Ergebnisse spiegeln deine persönliche Wahrnehmung der letzten 4 Wochen wider und können sich verändern.',\n  'Wenn du eine Krise, Gewalt oder eine Bedrohung deiner Sicherheit erlebst, wende dich an eine Fachperson oder an die Notdienste deines Landes.'\n];\n/* Точка А → точка Б: если в TEST_INFO есть from / to / key — показываем, с чем человек приходит и с чем уходит. */\nfunction abHtml(){\n  if (typeof TEST_INFO === 'undefined' || !TEST_INFO.from) return '';\n  const ps = a => [].concat(a).map(x => `<p>${x}</p>`).join('');\n  return `<div class=\"ab\"><div class=\"ab-a\"><span class=\"ab-l\">Punkt A · womit du kommst</span>${ps(TEST_INFO.from)}</div>\n    <div class=\"ab-arrow\" aria-hidden=\"true\"><svg viewBox=\"0 0 40 24\" width=\"40\" height=\"24\"><path d=\"M2 12h32M26 4l8 8-8 8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></div>\n    <div class=\"ab-b\"><span class=\"ab-l\">Punkt B · womit du gehst</span>${ps(TEST_INFO.to)}</div></div>\n    ${TEST_INFO.key ? `<div class=\"ab-key\"><b>Die wichtigste Einsicht</b><p>${TEST_INFO.key}</p></div>` : ''}`;\n}\nfunction testInfoHtml(){\n  if (typeof TEST_INFO === 'undefined') return '';\n  if (TEST_INFO.from) return `<div class=\"blk testinfo\"><div class=\"eyebrow\">Wozu der Test</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>${abHtml()}\n    <div class=\"ti-cols\"><div><h3>Was du damit machen kannst</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div></div></div>`;\n  return `<div class=\"blk testinfo\"><div class=\"eyebrow\">Über diesen Fragebogen</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>\n    <div class=\"ti-cols\">\n      <div><h3>Was dir der Test gibt</h3><ul class=\"clean\">${TEST_INFO.gives.map(x => `<li>${x}</li>`).join('')}</ul></div>\n      <div><h3>Was du damit tun kannst</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div>\n    </div></div>`;\n}\n/* Текст «Важно» сверяется по смыслу с каждым тестом: свой вариант — TEST_DISCLAIMER в meta.js (null = общая строка). */\nfunction disclaimerHtml(list){\n  const D = list || (typeof TEST_DISCLAIMER !== 'undefined' ? TEST_DISCLAIMER.map((x, i) => x || DISCLAIMER[i]).filter(Boolean) : DISCLAIMER);\n  return `<div class=\"disclaimer\"><b>Wichtig</b>${D.map(x => `<p>${x}</p>`).join('')}</div>`;\n}\n\n/* ---------- Поделиться тестом ---------- */\nconst SHARE_TEXT = {\n  'roza-lyubvi': ['Ich habe den Paartest «Die Rose der Liebe» gemacht. Spannend und sehr treffend. Mach ihn auch, dann vergleichen wir:',\n                  'Ich habe den Test «Die Rose der Liebe» entdeckt: 15 Minuten, und man sieht, welche Rollen in der Beziehung deutlich klingen und welche leiser geworden sind. Probier es aus:'],\n  'kompas':      ['Ich habe den Test «Kompass der Anpassung» gemacht, für alle, die in einem neuen Land leben. Er hilft sehr zu verstehen, wo man gerade steht. Probier es aus:',\n                  'Ich habe den Test «Kompass der Anpassung» entdeckt: 10 Minuten, und man sieht, was im neuen Land schon zur Stütze geworden ist und wo es noch still ist. Probier es aus:']\n};\nconst SHARE_ICON = {\n  share: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3v12M7 8l5-5 5 5M5 13v6a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>',\n  wa: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 20l1.2-4A8 8 0 1 1 8 18.8z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M9 9.5c0 3 2.5 5.5 5.5 5.5l1-1.5-2-1-1 1c-1-.5-1.5-1-2-2l1-1-1-2z\" fill=\"currentColor\"/></svg>',\n  tg: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 4 3 11l6 2 2 6 3-4 5 4z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"m9 13 8-6\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>',\n  copy: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"8\" y=\"8\" width=\"12\" height=\"12\" rx=\"2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>'\n};\nfunction shareData(){\n  const t = TESTS.find(x => typeof TEST_META !== 'undefined' && x.id === TEST_META.id) || TESTS[0];\n  return { url: testUrl(t), text: pickOne(SHARE_TEXT[t.id] || ['Probier diesen Test aus:']), title: t.name };\n}\nfunction shareHtml(compact){\n  if (typeof TEST_META === 'undefined') return '';\n  const head = compact\n    ? `<p class=\"note\">Kennst du jemanden, dem dieser Test auch helfen könnte? Leite den Link weiter.</p>`\n    : `<div class=\"eyebrow\">Teilen</div><h3>Schick den Test deinen Freundinnen und Freunden</h3><p>Wenn dir der Test geholfen hat, schick ihn Menschen, denen er auch helfen kann. ${TEST_META.id === 'roza-lyubvi' ? 'Noch besser: Schlag deinem Partner oder deiner Partnerin vor, ihn auch zu machen, und vergleicht eure Ergebnisse.' : 'Vor allem denen, die auch vor kurzem umgezogen sind.'}</p>`;\n  return `<div class=\"${compact ? 'share compact' : 'blk share'}\">${head}\n    <div class=\"share-btns\">\n      ${navigator.share ? `<button type=\"button\" class=\"main\" data-share-act=\"native\">${SHARE_ICON.share}Teilen</button>` : ''}\n      <button type=\"button\" data-share-act=\"wa\">${SHARE_ICON.wa}WhatsApp</button>\n      <button type=\"button\" data-share-act=\"tg\">${SHARE_ICON.tg}Telegram</button>\n      <button type=\"button\" data-share-act=\"copy\">${SHARE_ICON.copy}Link kopieren</button>\n    </div>\n    <div class=\"share-link\" hidden><input readonly aria-label=\"Link zum Test\"></div>\n    <span class=\"share-ok\" hidden></span></div>`;\n}\nfunction openExternal(url){\n  const w = window.open(url, '_blank', 'noopener');\n  if (!w) location.href = url;\n}\ndocument.addEventListener('click', async (ev) => {\n  const b = ev.target.closest('[data-share-act]'); if (!b) return;\n  const box = b.closest('.share'), d = shareData(), act = b.dataset.shareAct;\n  const ok = box.querySelector('.share-ok');\n  const showOk = t => { ok.textContent = t; ok.hidden = false; setTimeout(() => ok.hidden = true, 4000); };\n  if (act === 'native'){\n    try { await navigator.share({ title: d.title, text: d.text, url: d.url }); return; }\n    catch(e){ if (e && e.name === 'AbortError') return; }\n  }\n  if (act === 'wa') return openExternal('https://wa.me/?text=' + encodeURIComponent(d.text + ' ' + d.url));\n  if (act === 'tg') return openExternal('https://t.me/share/url?url=' + encodeURIComponent(d.url) + '&text=' + encodeURIComponent(d.text));\n  try { await navigator.clipboard.writeText(d.text + ' ' + d.url); showOk('Link kopiert. Füge ihn in eine Nachricht an eine Freundin oder einen Freund ein.'); }\n  catch(e){\n    const row = box.querySelector('.share-link'), inp = row.querySelector('input');\n    inp.value = d.url; row.hidden = false; inp.focus(); inp.select();\n    showOk('Kopiere den Link aus dem Feld oben.');\n  }\n});\n\n/* ---------- Отрисовка общих блоков на странице ---------- */\ndocument.documentElement.dataset.brand = BRAND;\ndocument.querySelectorAll('[data-author]').forEach(el => el.innerHTML = authorHtml());\ndocument.querySelectorAll('[data-greeting]').forEach(el => el.innerHTML = greetingHtml());\ndocument.querySelectorAll('[data-testinfo]').forEach(el => el.innerHTML = testInfoHtml());\ndocument.querySelectorAll('[data-disclaimer]').forEach(el => el.innerHTML = disclaimerHtml());\n/* копирайт внизу каждой страницы сайта */\n(function(){ const w = document.querySelector('.wrap'); if (!w || w.querySelector('.copy')) return;\n  const f = document.createElement('footer'); f.className = 'copy'; f.textContent = '© ' + new Date().getFullYear() + ' Iryna Voznesenskaya. Alle Rechte vorbehalten.'; w.appendChild(f); })();\ndocument.querySelectorAll('[data-share]').forEach(el => el.innerHTML = shareHtml(el.dataset.share === 'compact'));\n(function(){\n  const go = document.getElementById('svGo'); if (!go) return;\n  try { (JSON.parse(localStorage.getItem('irinaTestsSurvey') || '[]') || []).forEach(id => { const c = document.getElementById(id); if (c) c.checked = true; }); } catch(e){}\n  go.addEventListener('click', () => {\n    const a = surveyAnswers(), err = document.getElementById('svErr');\n    const miss = !a.heard.length ? 'Kreuze bitte an, woher du mich kennst.' : !a.interest.length ? 'Kreuze bitte an, was dich interessiert.' : '';\n    err.textContent = miss; err.hidden = !miss;\n    if (miss) return;\n    try { localStorage.setItem('irinaTestsSurvey', JSON.stringify([...document.querySelectorAll('input[data-sv]:checked')].map(i => i.id))); } catch(e){}\n    document.querySelector('[data-greeting]').hidden = true;\n    document.getElementById('testStart').hidden = false;\n    window.scrollTo(0, 0);\n  });\n})();\n", "/* =====================================================================\n   Данные и конфиденциальность — общее для всех тестов (с 02.10.2026).\n   - Ответы тестов хранятся только в браузере человека и через 90 дней удаляются сами.\n   - Кнопка «Удалить мои ответы».\n   - Страна спрашивается в мини-опросе (раньше — в анкете перед PDF).\n   - Ссылки на Политику конфиденциальности и Выходные данные в подвале.\n   Тексты на четырёх языках — здесь же (PRIV). Подключается после brand.js, до теста.\n   ===================================================================== */\nconst PAGE_LANG = (typeof LANG !== 'undefined') ? LANG : 'ru';\nconst DATA_DAYS = 90;\n\n/* Страны — коды ISO; названия показываются на языке страницы, в таблицу уходит русское название. */\nconst COUNTRY_TOP = ['CH','DE','AT','FR','IT','ES','NL','BE','GB','PL','CZ','IL','US','CA','UA','RU','BY','KZ'];\nconst COUNTRY_ALL = ['AU','AT','AZ','AL','DZ','AD','AR','AM','AF','BD','BH','BY','BE','BG','BO','BA','BR','GB','HU','VE','VN','GH','DE','HK','GR','GE','DK','DO','EG','IL','IN','ID','JO','IQ','IR','IE','IS','ES','IT','KZ','KH','CA','QA','KE','CY','KG','CN','CO','CR','CU','KW','LV','LB','LT','LI','LU','MU','MY','MV','MT','MA','MX','MD','MC','MN','ME','NP','NG','NL','NZ','NO','AE','OM','PK','PA','PY','PE','PL','PT','RU','RO','SA','MK','RS','SG','SK','SI','US','TJ','TH','TW','TN','TM','TR','UG','UZ','UA','UY','PH','FI','FR','HR','CZ','CL','CH','SE','LK','EC','EE','ZA','KR','JM','JP'];\nconst countryName = (() => { try { const d = new Intl.DisplayNames([PAGE_LANG], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst countryRu = (() => { try { const d = new Intl.DisplayNames(['ru'], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst COUNTRIES = COUNTRY_ALL.map(countryRu);\nconst OTHER_COUNTRY = 'Другая страна';\n\nconst PRIV_ALL = {\n  ru: {\n    countryQ: 'Где ты сейчас живёшь?', countryPick: 'Выбери страну', countryTop: 'Часто выбирают', countryAll: 'Все страны', countryOther: 'Другая страна',\n    countryErr: 'Выбери, пожалуйста, страну, в которой ты сейчас живёшь.',\n    countryNote: 'Страна нужна, чтобы показать в разборе подходящее приглашение и полезные ссылки.',\n    privacy: 'Политика конфиденциальности', impressum: 'Выходные данные', home: 'Главная', allTests: 'Все тесты',\n    onlyYou: 'Твои ответы остаются только у тебя. Я их не вижу.',\n    keepUntil: d => `Твои ответы и разбор хранятся только на этом устройстве, до ${d}. Потом они удалятся сами. Скачай PDF, если хочешь сохранить разбор.`,\n    del: 'Удалить мои ответы', delAsk: 'Удалить все ответы этого теста с этого устройства? Разбор тоже исчезнет. Если хочешь его сохранить, сначала скачай PDF.',\n    delYes: 'Да, удалить', delNo: 'Отмена', delDone: 'Ответы удалены с этого устройства.'\n  },\n  uk: {\n    countryQ: 'Де ти зараз живеш?', countryPick: 'Обери країну', countryTop: 'Часто обирають', countryAll: 'Усі країни', countryOther: 'Інша країна',\n    countryErr: 'Обери, будь ласка, країну, у якій ти зараз живеш.',\n    countryNote: 'Країна потрібна, щоб показати в розборі відповідне запрошення та корисні посилання.',\n    privacy: 'Політика конфіденційності', impressum: 'Вихідні дані', home: 'Головна', allTests: 'Усі тести',\n    onlyYou: 'Твої відповіді залишаються тільки в тебе. Я їх не бачу.',\n    keepUntil: d => `Твої відповіді та розбір зберігаються тільки на цьому пристрої, до ${d}. Потім вони видаляться самі. Завантаж PDF, якщо хочеш зберегти розбір.`,\n    del: 'Видалити мої відповіді', delAsk: 'Видалити всі відповіді цього тесту з цього пристрою? Розбір теж зникне. Якщо хочеш його зберегти, спочатку завантаж PDF.',\n    delYes: 'Так, видалити', delNo: 'Скасувати', delDone: 'Відповіді видалено з цього пристрою.'\n  },\n  de: {\n    countryQ: 'Wo lebst du zurzeit?', countryPick: 'Wähle ein Land', countryTop: 'Häufig gewählt', countryAll: 'Alle Länder', countryOther: 'Anderes Land',\n    countryErr: 'Wähle bitte das Land, in dem du zurzeit lebst.',\n    countryNote: 'Das Land brauche ich, um dir in der Auswertung die passende Einladung und hilfreiche Links zu zeigen.',\n    privacy: 'Datenschutzerklärung', impressum: 'Impressum', home: 'Startseite', allTests: 'Alle Tests',\n    onlyYou: 'Deine Antworten bleiben nur bei dir. Ich sehe sie nicht.',\n    keepUntil: d => `Deine Antworten und die Auswertung sind nur auf diesem Gerät gespeichert, bis ${d}. Danach werden sie automatisch gelöscht. Lade das PDF herunter, wenn du die Auswertung behalten möchtest.`,\n    del: 'Meine Antworten löschen', delAsk: 'Alle Antworten dieses Tests von diesem Gerät löschen? Auch die Auswertung verschwindet. Wenn du sie behalten möchtest, lade zuerst das PDF herunter.',\n    delYes: 'Ja, löschen', delNo: 'Abbrechen', delDone: 'Die Antworten wurden von diesem Gerät gelöscht.'\n  },\n  en: {\n    countryQ: 'Where do you live now?', countryPick: 'Choose a country', countryTop: 'Frequently chosen', countryAll: 'All countries', countryOther: 'Other country',\n    countryErr: 'Please choose the country where you live now.',\n    countryNote: 'I need the country to show you the right invitation and useful links in your results.',\n    privacy: 'Privacy policy', impressum: 'Legal notice', home: 'Home', allTests: 'All tests',\n    onlyYou: 'Your answers stay with you only. I cannot see them.',\n    keepUntil: d => `Your answers and results are stored only on this device, until ${d}. After that they are deleted automatically. Download the PDF if you want to keep your results.`,\n    del: 'Delete my answers', delAsk: 'Delete all answers to this test from this device? Your results will disappear too. If you want to keep them, download the PDF first.',\n    delYes: 'Yes, delete', delNo: 'Cancel', delDone: 'Your answers have been deleted from this device.'\n  }\n};\nconst PRIV = PRIV_ALL[PAGE_LANG] || PRIV_ALL.ru;\n\n/* ---------- 1. Автоудаление ответов через 90 дней ---------- */\n(function purge(){\n  try {\n    const limit = Date.now() - DATA_DAYS * 864e5;\n    for (let i = localStorage.length - 1; i >= 0; i--){\n      const k = localStorage.key(i);\n      if (!k || !/^irinaTests\\./.test(k)) continue;\n      let v = null; try { v = JSON.parse(localStorage.getItem(k) || 'null'); } catch(e){}\n      const t = v && (v.t || v.startedAt);\n      if (!t || t < limit) localStorage.removeItem(k);\n    }\n    localStorage.removeItem('irinaTestsLead');   // прежняя анкета (с e-mail) больше не хранится\n  } catch(e){}\n})();\n\n/* ключ сохранённых ответов текущего теста */\nfunction answersKey(){ return (typeof TEST_META !== 'undefined') ? 'irinaTests.' + TEST_META.id + '.v1' : ''; }\nfunction answersSavedAt(){ try { const v = JSON.parse(localStorage.getItem(answersKey()) || 'null'); return v ? (v.t || v.startedAt || 0) : 0; } catch(e){ return 0; } }\nfunction retentionLine(){\n  const t = answersSavedAt() || Date.now();\n  const d = new Date(t + DATA_DAYS * 864e5).toLocaleDateString(typeof DATE_LOCALE !== 'undefined' ? DATE_LOCALE : 'ru-RU', { day:'2-digit', month:'2-digit', year:'numeric' });\n  return PRIV.keepUntil(d);\n}\n\n/* ---------- 2. Страна в мини-опросе ---------- */\nconst COUNTRY_KEY = 'irinaTestsCountry';\nfunction surveyCountry(){\n  const s = document.getElementById('svCountry');\n  if (s && s.value) return s.value;\n  try { return localStorage.getItem(COUNTRY_KEY) || ''; } catch(e){ return ''; }\n}\n// Тесты раньше брали страну из анкеты (window.__leadCountry). Теперь она всегда берётся из мини-опроса.\ntry { Object.defineProperty(window, '__leadCountry', { configurable: true, get: surveyCountry, set: () => {} }); } catch(e){}\n\nfunction countrySelectHtml(id){\n  return `<select id=\"${id}\"><option value=\"\">${PRIV.countryPick}</option></select>`;\n}\nfunction fillCountrySelect(sel, value){\n  if (!sel || sel.options.length > 1) return;\n  const g1 = document.createElement('optgroup'); g1.label = PRIV.countryTop;\n  COUNTRY_TOP.forEach(c => g1.appendChild(new Option(countryName(c), countryRu(c))));\n  const g2 = document.createElement('optgroup'); g2.label = PRIV.countryAll;\n  COUNTRY_ALL.map(c => [countryName(c), countryRu(c)]).sort((x, y) => x[0].localeCompare(y[0], PAGE_LANG)).forEach(([n, v]) => g2.appendChild(new Option(n, v)));\n  g2.appendChild(new Option(PRIV.countryOther, OTHER_COUNTRY));\n  sel.appendChild(g1); sel.appendChild(g2);\n  if (value && (COUNTRIES.includes(value) || value === OTHER_COUNTRY)) sel.value = value;\n}\n(function surveyCountryField(){\n  const box = document.querySelector('[data-greeting] .surveys'); if (!box || document.getElementById('svCountry')) return;\n  const fs = document.createElement('fieldset'); fs.className = 'survey sv-country';\n  fs.innerHTML = `<legend>${PRIV.countryQ} *</legend>${countrySelectHtml('svCountry')}<p class=\"note\">${PRIV.countryNote}</p>`;\n  box.appendChild(fs);\n  let saved = ''; try { saved = localStorage.getItem(COUNTRY_KEY) || ''; } catch(e){}\n  const sel = fs.querySelector('select'); fillCountrySelect(sel, saved);\n  sel.addEventListener('change', () => { try { localStorage.setItem(COUNTRY_KEY, sel.value); } catch(e){} });\n  // без страны тест не открывается (проверка срабатывает раньше общей кнопки «Перейти к тестированию»)\n  document.addEventListener('click', ev => {\n    const go = ev.target.closest && ev.target.closest('#svGo'); if (!go) return;\n    const a = (typeof surveyAnswers === 'function') ? surveyAnswers() : { heard: [1], interest: [1] };\n    if (!a.heard.length || !a.interest.length) return;          // об этих вопросах скажет общая проверка\n    if (!sel.value){\n      ev.stopPropagation(); ev.preventDefault();\n      const err = document.getElementById('svErr'); if (err){ err.textContent = PRIV.countryErr; err.hidden = false; }\n      sel.focus();\n    } else { try { localStorage.setItem(COUNTRY_KEY, sel.value); } catch(e){} }\n  }, true);\n})();\n\n/* ---------- 3. Удалить мои ответы ---------- */\nfunction deleteAnswersHtml(){\n  if (!answersKey()) return '';\n  return `<div class=\"del-answers\"><button type=\"button\" class=\"linkbtn\" data-del-answers>${PRIV.del}</button>\n    <div class=\"del-ask\" hidden><p>${PRIV.delAsk}</p><div class=\"row\"><button type=\"button\" class=\"btn small\" data-del-yes>${PRIV.delYes}</button><button type=\"button\" class=\"btn ghost small\" data-del-no>${PRIV.delNo}</button></div></div>\n    <p class=\"note del-done\" hidden>${PRIV.delDone}</p></div>`;\n}\ndocument.addEventListener('click', ev => {\n  const b = ev.target.closest && ev.target.closest('[data-del-answers],[data-del-yes],[data-del-no]'); if (!b) return;\n  const box = b.closest('.del-answers'), ask = box.querySelector('.del-ask');\n  if (b.hasAttribute('data-del-answers')){ ask.hidden = !ask.hidden; return; }\n  if (b.hasAttribute('data-del-no')){ ask.hidden = true; return; }\n  try {\n    const pre = 'irinaTests.' + TEST_META.id + '.';\n    for (let i = localStorage.length - 1; i >= 0; i--){ const k = localStorage.key(i); if (k && k.indexOf(pre) === 0) localStorage.removeItem(k); }\n  } catch(e){}\n  ask.hidden = true; box.querySelector('.del-done').hidden = false;\n  setTimeout(() => { location.hash = ''; location.reload(); }, 900);\n});\n\n/* ---------- 4. Подвал: правовые ссылки и удаление ответов ---------- */\nfunction legalUrl(page){\n  const root = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n  return root + page + '/';\n}\nfunction privacyLinksHtml(){\n  const root = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n  return `<a href=\"${root}\">${PRIV.home}</a> · <a href=\"${root}testy/\">${PRIV.allTests}</a> · <a href=\"${legalUrl('privacy')}\">${PRIV.privacy}</a> · <a href=\"${legalUrl('impressum')}\">${PRIV.impressum}</a>`;\n}\n(function footer(){\n  const f = document.querySelector('.wrap .copy'); if (!f || f.querySelector('.legal-links')) return;\n  const p = document.createElement('span'); p.className = 'legal-links'; p.innerHTML = privacyLinksHtml();\n  f.appendChild(document.createElement('br')); f.appendChild(p);\n  if (answersKey() && document.getElementById('intro')){\n    const d = document.createElement('div'); d.innerHTML = deleteAnswersHtml(); f.appendChild(d.firstElementChild);\n  }\n})();\n/* строка «Твои ответы остаются только у тебя» на стартовой странице, рядом с кнопкой начала */\n(function startNote(){\n  const host = document.querySelector('#testStart [data-share=\"compact\"]'); if (!host || document.querySelector('.only-you')) return;\n  const p = document.createElement('p'); p.className = 'note only-you';\n  p.innerHTML = `${PRIV.onlyYou} <a href=\"${legalUrl('privacy')}\">${PRIV.privacy}</a>`;\n  host.parentNode.insertBefore(p, host);\n})();\n\n/* ---------- 6. Общая шапка сайта на каждой странице (тесты, «Тесты», правовые) — вернуться можно откуда угодно ---------- */\n(function siteHeader(){\n  if (document.querySelector('.sitebar')) return;\n  const root = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n  const T = {\n    ru: { sub: 'коуч ICF · Цюрих', name: 'Ирина Вознесенская', nav: ['С чего начать', 'Твой путь', 'Обо мне', 'Тесты', 'Контакт'], cta: 'Знакомство' },\n    uk: { sub: 'коуч ICF · Цюрих', name: 'Ірина Вознесенська', nav: ['З чого почати', 'Твій шлях', 'Про мене', 'Тести', 'Контакт'], cta: 'Знайомство' },\n    de: { sub: 'ICF-Coach · Zürich', name: 'Iryna Voznesenskaya', nav: ['Wo anfangen', 'Dein Weg', 'Über mich', 'Tests', 'Kontakt'], cta: 'Kennenlernen' },\n    en: { sub: 'ICF coach · Zurich', name: 'Iryna Voznesenskaya', nav: ['Where to start', 'Your path', 'About me', 'Tests', 'Contact'], cta: 'Intro call' }\n  }[PAGE_LANG] || {};\n  const L = T.nav ? T : { sub: 'коуч ICF · Цюрих', name: 'Ирина Вознесенская', nav: ['С чего начать', 'Твой путь', 'Обо мне', 'Тесты', 'Контакт'], cta: 'Знакомство' };\n  const hrefs = [root + '#doors', root + 'put/', root + '#about', root + 'testy/', root + '#contact'];\n  const here = location.pathname.replace(/\\/+$/, '').split('/').pop();\n  const h = document.createElement('header'); h.className = 'sitebar';\n  h.innerHTML = `<div class=\"sitebar-in\">\n    <a class=\"sb-mark\" href=\"${root}\"><span class=\"sb-mono av\">${typeof AVATAR_SVG !== \"undefined\" ? AVATAR_SVG : \"ИВ\"}</span><span><b>${L.name}</b><small>${L.sub}</small></span></a>\n    <nav class=\"sb-nav\" aria-label=\"Menu\">${L.nav.map((t, i) => `<a href=\"${hrefs[i]}\"${i === 3 && here === 'testy' ? ' aria-current=\"page\"' : ''}>${t}</a>`).join('')}</nav>\n    <a class=\"sb-cta\" href=\"https://t.me/IrynaNeuroCoach\" target=\"_blank\" rel=\"noopener\">${L.cta}</a></div>`;\n  document.body.insertBefore(h, document.body.firstChild);\n})();\n", "/* Правовые страницы: адрес и e-mail берутся из config.js (LEGAL). Пока они не заданы — показывается временная строка. */\n(function(){\n  const L = (typeof LEGAL !== 'undefined') ? LEGAL : {};\n  const lang = (typeof PAGE_LANG !== 'undefined' && PAGE_LANG) || document.documentElement.lang || 'ru';\n  const pick = v => (v && typeof v === 'object') ? (v[lang] || v.ru || '') : (v || '');\n  const has = !!pick(L.address), hasMail = !!L.email;\n  document.querySelectorAll('[data-legal]').forEach(e => {\n    const k = e.dataset.legal, v = pick(L[k]);\n    if (k === 'email' && v) e.innerHTML = `<a href=\"mailto:${v}\">${v}</a>`;\n    else if (k === 'address' && v) e.innerHTML = v.split('\\n').join('<br>');\n    else e.textContent = v;\n  });\n  document.querySelectorAll('[data-legal-has]').forEach(e => e.hidden = !has);\n  document.querySelectorAll('[data-legal-missing]').forEach(e => e.hidden = hasMail);\n  document.querySelectorAll('[data-legal-mail]').forEach(e => e.hidden = !hasMail);\n  document.querySelectorAll('[data-legal-since]').forEach(e => e.textContent = L.since || '');\n  document.querySelectorAll('[data-legal-year]').forEach(e => e.textContent = new Date().getFullYear());\n  document.querySelectorAll('[data-legal-days]').forEach(e => e.textContent = (typeof DATA_DAYS !== 'undefined') ? DATA_DAYS : 90);\n  const back = document.querySelector('[data-legal-back]'); if (back) back.href = (typeof SITE_BASE !== 'undefined' ? SITE_BASE : '../') + 'testy/';\n})();\n"]};
